let planNetwork='metro',planService='301',planDirection='south';
const metroStations=[...new Set(TRANSIT_CATALOG.filter(r=>r.network==='metro').flatMap(r=>r.corridor))];
const serviceLabels=(r,d)=>r[d].map((s,i)=>r[d].filter(x=>x===s).length>1?s+' (parada '+(i+1)+')':s);
function availablePlannerStations(){return planNetwork==='metro'?metroStations:serviceLabels(TRANSIT_CATALOG.find(r=>r.id===planService),planDirection)}
function changePlanNetwork(n){planNetwork=n;if(n!=='metro')planService=TRANSIT_CATALOG.find(r=>r.network===n).id;resetPlanEndpoints()}
function resetPlanEndpoints(){const ss=availablePlannerStations();origin=ss[0];destination=ss.at(-1);showRoutes=false;choice=0;render()}
function planFromService(id,dir){const r=TRANSIT_CATALOG.find(r=>r.id===id);planNetwork=r.network;planService=id;planDirection=dir;origin=serviceLabels(r,dir)[0];destination=serviceLabels(r,dir).at(-1);showRoutes=false;choice=0;go('plan')}
function makeLeg(r,dir,a,b){const ss=r[dir];return {routeId:r.id,name:r.name,direction:dir,towards:ss.at(-1),from:ss[a],to:ss[b],stops:ss.slice(a,b+1),minutes:Math.max(3,(b-a)*3),startIndex:a,endIndex:b}}
function findJourneys(from,to,sort='changes'){
 if(from===to)return [];
 const results=[];
 function push(legs){const duration=4+legs.reduce((n,l)=>n+l.minutes+5,0)+(legs.length-1)*3;results.push({origin:from,destination:to,legs,duration,direction:'Hacia '+to,transfers:legs.length-1})}
 if(planNetwork!=='metro'){
  const r=TRANSIT_CATALOG.find(r=>r.id===planService),ss=serviceLabels(r,planDirection),a=ss.indexOf(from),b=ss.indexOf(to);
  if(a>=0&&b>a)push([makeLeg(r,planDirection,a,b)]);
  return results;
 }
 const services=TRANSIT_CATALOG.filter(r=>r.network==='metro').flatMap(r=>['south','north'].map(dir=>({r,dir,ss:r[dir]})));
 for(const s of services){const a=s.ss.indexOf(from),b=s.ss.indexOf(to);if(a<0)continue;if(b>a)push([makeLeg(s.r,s.dir,a,b)]);
  for(let i=a+1;i<s.ss.length;i++)for(const t of services){if(t.r.id===s.r.id)continue;const j=t.ss.indexOf(s.ss[i]),end=t.ss.indexOf(to);if(j<0||end<=j)continue;const l1=makeLeg(s.r,s.dir,a,i),l2=makeLeg(t.r,t.dir,j,end);if(l2.stops.slice(1).some(x=>l1.stops.includes(x)))continue;push([l1,l2])}
 }
 const unique=new Map();for(const r of results){const key=r.legs.map(l=>l.routeId+':'+l.direction).join('/');if(!unique.has(key)||r.duration<unique.get(key).duration)unique.set(key,r)}
 const all=[...unique.values()];if(sort==='all')return all;return all.filter(a=>!all.some(b=>b!==a&&b.transfers<=a.transfers&&b.duration<=a.duration&&(b.transfers<a.transfers||b.duration<a.duration))).sort((a,b)=>sort==='time'?a.duration-b.duration||a.transfers-b.transfers:a.transfers-b.transfers||a.duration-b.duration).slice(0,4);
}
const plannerOptions=s=>availablePlannerStations().map(n=>`<option ${n===s?'selected':''}>${esc(n)}</option>`).join('');
function plannerSources(ids){const rr=TRANSIT_CATALOG.filter(r=>ids?ids.includes(r.id):planNetwork==='metro'?r.network==='metro':r.id===planService);return `<section class="card route-sources"><h3>Recorridos y fuentes</h3><p>12 servicios de referencia. Mapas y horarios recibidos el 10 de noviembre de 2026; Expreso 13 conserva la publicación ATU consultada anteriormente.</p>${rr.map(r=>`<details><summary>${r.name}</summary><p>${esc(r.sourceNote)}</p>${r.note?`<p>${esc(r.note)}</p>`:''}${['south','north'].map(d=>`<p>${esc(r[d][0])} → ${esc(r[d].at(-1))}</p>${r.maps[d]?`<a href="maps/${r.maps[d]}.png" target="_blank" rel="noopener">Ver mapa de este sentido ↗</a>`:''}`).join('')}${r.sources.map(s=>`<a href="${s.url}" target="_blank" rel="noopener">${s.label} ↗</a>`).join('')}</details>`).join('')}<p class="small muted">El catálogo es parcial y no se sincroniza automáticamente. Los horarios no garantizan disponibilidad en el momento del viaje.</p><a href="${ATU_ROUTE_DATA.portal}" target="_blank" rel="noopener">Consultar portal ATU ↗</a></section>`}
function journeySteps(r){return r.legs.map((l,i)=>{const service=TRANSIT_CATALOG.find(x=>x.id===l.routeId);return `<div class="journey-leg"><span class="pill teal">${i+1} · ${esc(l.name)}</span><h3>${esc(l.from)} → ${esc(l.to)}</h3><p class="small muted">Aborda hacia ${esc(l.towards)}</p><details><summary>Ver ${l.stops.length} paradas del tramo</summary><ol>${l.stops.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></details>${service?`<details><summary>Consultar horario de este sentido</summary>${scheduleView(service,l.direction)}</details>`:''}${i<r.legs.length-1?`<div class="transfer-note">${icon('swap')} Cambia a ${esc(r.legs[i+1].name)} en ${esc(l.to)}</div>`:''}</div>`}).join('')}
function referencePlan(){const options=showRoutes?findJourneys(origin,destination,preference):[];return heading('Cada viaje, un mejor plan.','Elige un servicio y consulta tus opciones con las paradas proporcionadas.')+`<div class="network-tabs">${Object.entries(NETWORK_NAMES).map(([id,n])=>`<button class="chip ${planNetwork===id?'selected':''}" onclick="changePlanNetwork('${id}')">${n}</button>`).join('')}</div><div class="grid"><div class="stack"><section class="card"><span class="eyebrow muted">TU RECORRIDO · ${NETWORK_NAMES[planNetwork]}</span>${planNetwork!=='metro'?`<label class="spaced" for="plan-service">Servicio</label><select id="plan-service" onchange="planService=this.value;resetPlanEndpoints()">${TRANSIT_CATALOG.filter(r=>r.network===planNetwork).map(r=>`<option value="${r.id}" ${r.id===planService?'selected':''}>${r.name}</option>`).join('')}</select><label class="spaced" for="plan-direction">Sentido</label><select id="plan-direction" onchange="planDirection=this.value;resetPlanEndpoints()">${['south','north'].map(d=>{const ss=TRANSIT_CATALOG.find(r=>r.id===planService)[d];return `<option value="${d}" ${d===planDirection?'selected':''}>${esc(ss[0])} → ${esc(ss.at(-1))}</option>`}).join('')}</select>`:''}<label class="spaced" for="origin">ORIGEN</label><select id="origin" onchange="origin=this.value;showRoutes=false;render()">${plannerOptions(origin)}</select>${planNetwork==='metro'?`<div style="text-align:right;margin:10px 0"><button class="text-btn" onclick="[origin,destination]=[destination,origin];showRoutes=false;render()">${icon('swap')} Intercambiar</button></div>`:''}<label class="spaced" for="dest">DESTINO</label><select id="dest" onchange="destination=this.value;showRoutes=false;render()">${plannerOptions(destination)}</select><p class="detail-label">¿Qué prefieres?</p><div class="options">${[['changes','Menos transbordos'],['time','Menor tiempo · simulado']].map(([k,t])=>`<button class="chip ${preference===k?'selected':''}" onclick="preference='${k}';choice=0;render()">${t}</button>`).join('')}</div><button class="primary full spaced" onclick="searchRoutes()">Buscar opciones de viaje ${icon('arrow')}</button><p class="small muted">${planNetwork==='metro'?'Compara servicios del Metropolitano, con hasta un transbordo.':'Planifica dentro del servicio y sentido seleccionados. Las conexiones entre corredores aún no están incluidas.'} Sin datos reales de aforo o llegadas.</p></section>${plannerSources()}</div><div class="stack">${showRoutes?`<div class="section-title"><h3>${esc(origin)} → ${esc(destination)}</h3><span class="pill teal">${options.length} opciones</span></div>${options.length?options.map((r,i)=>`<button class="card route-card ${choice===i?'selected':''}" aria-pressed="${choice===i}" onclick="choice=${i};render()"><div class="row between"><strong>${r.legs.map(l=>l.name).join(' → ')}</strong>${choice===i?icon('check'):''}</div><div class="row between spaced"><span class="route-min">${r.duration} <small>min</small></span><span class="pill">${r.transfers?'1 transbordo':'Directo'}</span></div><p class="small muted">Tiempo simulado, no estimación real</p><p>${r.transfers?'Cambio en '+r.legs[0].to:'Sin cambiar de bus'}</p></button>`).join('')+`<button class="primary full" onclick="openTrip()">Ver este viaje ${icon('arrow')}</button><p class="small muted">Revisa los horarios en el detalle. La búsqueda compara paradas; no comprueba la operación a una hora concreta.</p>`:`<section class="card"><h3>No encontramos una opción</h3><p>Revisa el sentido y el orden de tus paradas. La búsqueda se limita a los servicios cargados; podrían existir otras opciones.</p><a class="text-btn" href="${ATU_ROUTE_DATA.portal}" target="_blank" rel="noopener">Consultar ATU ↗</a></section>`}`:`<section class="card"><span class="pill teal">${NETWORK_NAMES[planNetwork]}</span><h2 class="spaced">Conecta tu recorrido</h2><p class="muted">Paradas por sentido, horarios de operación y mapas de referencia.</p>${planNetwork==='metro'?'<p>Servicios disponibles: A, B, C, D, Expreso 1, Súper Expreso y Expreso 13.</p><p class="small muted">La ida y el retorno pueden tener distintas paradas. Los servicios expresos no se detienen en todas las estaciones.</p>':scheduleView(TRANSIT_CATALOG.find(r=>r.id===planService),planDirection)}<button class="secondary full spaced" onclick="${planNetwork==='metro'?"go('live')":`liveRouteId=planService;liveDirection=planDirection;simProgress=0;go('live')`}">Ver recorrido y simulación</button></section>`}</div></div>`}
function referenceTrip(r){return heading(data.active?'Tu viaje está en marcha':'Tu viaje a '+esc(r.destination),`${esc(r.origin)} → ${esc(r.destination)} · Recorrido de referencia`)+`<div class="grid"><section class="card"><div class="row between"><span class="route-min">${r.duration} <small>min · simulados</small></span><span class="pill teal">${r.transfers===0?'Sin transbordos':r.transfers+' transbordo'+(r.transfers>1?'s':'')}</span></div>${journeySteps(r)}<p class="small muted">Esquema de paradas, sin GPS. El tiempo incluye esperas y caminatas ilustrativas; confirma horarios y operación en ATU.</p></section><div class="stack"><section class="card">${data.active?`<span class="pill green">Pasaje registrado</span><p>${money(data.active.cost)} descontados de ${esc(data.active.cardName)}.</p><button class="primary full" onclick="finishTrip()">Finalizar viaje</button>`:`<h3>Elige tu tarjeta</h3><select class="spaced" aria-label="Tarjeta de pago" onchange="selectCard(this.value)">${data.cards.map(c=>`<option value="${c.id}" ${c.id===card().id?'selected':''}>${esc(c.name)} · ${money(c.balance)}</option>`).join('')}</select><div class="row between spaced"><span>Pasaje simulado · ${r.legs.length} abordajes</span><strong>${money(fare()*r.legs.length)}</strong></div><p class="small muted">Modelo de prueba por abordaje, no tarifa oficial. Se descuenta una sola vez del saldo de ejemplo; no es un cobro real.</p><button class="primary full" onclick="startTrip()">Iniciar ruta ${icon('arrow')}</button>`}</section>${plannerSources(r.legs.map(l=>l.routeId))}</div></div>`}
